import { test, expect } from '@playwright/test';
import * as ui from '../support/ui';

test.setTimeout(240_000);
test.describe("rate versions", () => {
  test("rate versions", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-03-10");
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
    expect(await ui.setRole(pg_uma, "wes", "viewer")).toBe(true);
    expect(await ui.setRole(pg_uma, "vic", "steward")).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "20.00", "from": "2026-03-05"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "30.00", "from": "2026-03-05"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "12.00"})).toBe(true);
    const pg_wes = await ui.userPage(browser, "wes", sheet);
    expect(await ui.setRate(pg_wes, {"grade": "A", "pct": "70.00", "from": "2026-03-05"})).toBe(false);
    const pg_vic = await ui.userPage(browser, "vic", sheet);
    expect(await ui.delegate(pg_vic, {"user": "wes", "from": "2026-03-10", "to": "2026-03-12"})).toBe(true);
    await ui.refresh(pg_wes);
    expect(await ui.setRate(pg_wes, {"grade": "A", "pct": "25.00"})).toBe(true);
    await ui.refresh(pg_uma);
    const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "10.00", "date": "2026-03-01"}));
    const c_ada_1 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "10.00"}));
    expect(await ui.claimAction(pg_uma, c_ada_0, "open")).toBe(true);
    expect(await ui.claimAction(pg_uma, c_ada_1, "open")).toBe(true);
    await ui.refresh(pg_uma);
    await expect(pg_uma.getByTestId("person-row-" + p_ada).getByTestId("person-due-total")).toHaveText("5.50");
    await expect(pg_uma.getByTestId("claim-row-" + c_ada_1).getByTestId("claim-due")).toHaveText("3.00");
    await expect(pg_uma.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-due")).toHaveText("2.50");
    await expect(pg_uma.getByTestId("rollup-claimed-total")).toHaveText("20.00");
    await expect(pg_uma.getByTestId("rollup-due-total")).toHaveText("5.50");
    await expect(pg_uma.getByTestId("rollup-overdue-count")).toHaveText("0");
    await expect(pg_uma.getByTestId("rollup-overdue-total")).toHaveText("0.00");
    await expect(pg_uma.getByTestId("rollup-settled-total")).toHaveText("0.00");
    await expect(pg_uma.getByTestId("rollup-open-total")).toHaveText("5.50");
    await expect(pg_uma.getByTestId("bulk-settle-batch")).toHaveText("");
    await expect(pg_uma.getByTestId("rollup-cut-total")).toHaveText("0.00");
    await expect(pg_uma.getByTestId("rate-current-A")).toHaveText("30.00");
    await expect(pg_uma.getByTestId("rate-current-B")).toHaveText("n/a");
    await expect(pg_uma.getByTestId("rate-current-C")).toHaveText("n/a");
    await expect(pg_uma.getByTestId("rate-row-A-2026-03-05").getByTestId("rate-pct")).toHaveText("30.00");
    await expect(pg_uma.getByTestId("rate-row-A-2026-03-05").getByTestId("rate-version")).toHaveText("2");
    await expect(pg_uma.getByTestId("rate-row-A-start").getByTestId("rate-pct")).toHaveText("25.00");
    await expect(pg_uma.getByTestId("rate-row-A-start").getByTestId("rate-version")).toHaveText("3");
    expect(await ui.importRates(pg_uma, "A,40.00,2026-03-05\nB,1.00")).toBe(2);
    expect(await ui.statement(pg_uma, p_ada)).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "50.00", "from": "2026-03-05"})).toBe(true);
    await ui.refresh(pg_uma);
    await expect(pg_uma.getByTestId("person-row-" + p_ada).getByTestId("person-due-total")).toHaveText("6.50");
    await expect(pg_uma.getByTestId("claim-row-" + c_ada_1).getByTestId("claim-due")).toHaveText("4.00");
    await expect(pg_uma.getByTestId("claim-row-" + c_ada_1).getByTestId("claim-stated")).toHaveText("yes");
    await expect(pg_uma.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-due")).toHaveText("2.50");
    await expect(pg_uma.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-stated")).toHaveText("yes");
    await expect(pg_uma.getByTestId("rollup-claimed-total")).toHaveText("20.00");
    await expect(pg_uma.getByTestId("rollup-due-total")).toHaveText("6.50");
    await expect(pg_uma.getByTestId("rollup-overdue-count")).toHaveText("0");
    await expect(pg_uma.getByTestId("rollup-overdue-total")).toHaveText("0.00");
    await expect(pg_uma.getByTestId("rollup-settled-total")).toHaveText("0.00");
    await expect(pg_uma.getByTestId("rollup-open-total")).toHaveText("6.50");
    await expect(pg_uma.getByTestId("bulk-settle-batch")).toHaveText("");
    await expect(pg_uma.getByTestId("rollup-cut-total")).toHaveText("0.00");
    await expect(pg_uma.getByTestId("rate-current-A")).toHaveText("50.00");
    await expect(pg_uma.getByTestId("rate-current-B")).toHaveText("1.00");
    await expect(pg_uma.getByTestId("rate-current-C")).toHaveText("n/a");
    await expect(pg_uma.getByTestId("rate-row-A-start").getByTestId("rate-pct")).toHaveText("25.00");
    await expect(pg_uma.getByTestId("rate-row-A-start").getByTestId("rate-version")).toHaveText("3");
    await expect(pg_uma.getByTestId("rate-row-B-start").getByTestId("rate-pct")).toHaveText("1.00");
    await expect(pg_uma.getByTestId("rate-row-B-start").getByTestId("rate-version")).toHaveText("1");
    await expect(pg_uma.getByTestId("rate-row-A-2026-03-05").getByTestId("rate-pct")).toHaveText("50.00");
    await expect(pg_uma.getByTestId("rate-row-A-2026-03-05").getByTestId("rate-version")).toHaveText("4");
    await ui.expectAudit(sheet, [
      `PERSON_ADDED sheet=${sheet} by=uma name=Ada grade=A`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=0.00 due-total=n/a overdue-total=0.00`,
      `ROLE_SET sheet=${sheet} by=uma user=wes role=viewer`,
      `ROLE_SET sheet=${sheet} by=uma user=vic role=steward`,
      `RATE_SET sheet=${sheet} by=uma grade=A rate=10.00`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=0.00 due-total=0.00 overdue-total=0.00`,
      `RATE_SET sheet=${sheet} by=uma grade=A rate=20.00 from=2026-03-05`,
      `RATE_SET sheet=${sheet} by=uma grade=A rate=30.00 from=2026-03-05`,
      `RATE_SET sheet=${sheet} by=uma grade=A rate=12.00`,
      `DELEGATED sheet=${sheet} by=vic user=wes from=2026-03-10 to=2026-03-12`,
      `RATE_SET sheet=${sheet} by=wes grade=A rate=25.00 for=vic`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Ada amount=10.00 date=2026-03-01`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Ada amount=10.00 date=2026-03-10`,
      `CLAIM_OPENED sheet=${sheet} by=uma person=Ada amount=10.00 date=2026-03-01 number=FY2026-1`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=10.00 due-total=2.50 overdue-total=0.00`,
      `TOTALS sheet=${sheet} by=uma claimed-total=10.00 due-total=2.50 overdue-total=0.00`,
      `CLAIM_OPENED sheet=${sheet} by=uma person=Ada amount=10.00 date=2026-03-10 number=FY2026-2`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=20.00 due-total=5.50 overdue-total=0.00`,
      `TOTALS sheet=${sheet} by=uma claimed-total=20.00 due-total=5.50 overdue-total=0.00`,
      `RATE_SET sheet=${sheet} by=uma grade=A rate=40.00 from=2026-03-05`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=20.00 due-total=6.50 overdue-total=0.00`,
      `TOTALS sheet=${sheet} by=uma claimed-total=20.00 due-total=6.50 overdue-total=0.00`,
      `RATE_SET sheet=${sheet} by=uma grade=B rate=1.00`,
      `STATEMENT sheet=${sheet} by=uma name=Ada due-total=6.50 claims=2`,
      `RATE_SET sheet=${sheet} by=uma grade=A rate=50.00 from=2026-03-05`
    ]);
  });
